/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN
    DECLARE changes TEXT DEFAULT '';

    IF OLD.SKU <> NEW.SKU THEN
        SET changes = CONCAT(changes, 'SKU: [', OLD.SKU, '] -> [', NEW.SKU, '] ');
    END IF;

    IF OLD.name <> NEW.name THEN
        SET changes = CONCAT(changes, 'name: [', OLD.name, '] -> [', NEW.name, '] ');
    END IF;

    IF OLD.current_price <> NEW.current_price THEN
        SET changes = CONCAT(changes, 'current_price: [', OLD.current_price, '] -> [', NEW.current_price, '] ');
    END IF;

    IF OLD.current_stock <> NEW.current_stock THEN
        SET changes = CONCAT(changes, 'current_stock: [', OLD.current_stock, '] -> [', NEW.current_stock, '] ');
    END IF;

    INSERT INTO tb_logs (table_name, operation, db_user, description)
    VALUES (
        'tb_products',
        'Update',
        USER(),
        CONCAT('Producto actualizado. ID=', NEW.ID, '. Cambios: ', TRIM(changes))
    );
END */;;
DELIMITER ;
